        panic("usage: main <file>")

    let path = args.element_at(0)
    let fs = Fs()
    var text = ""
    match fs.read_file(path)
        Result.Ok(contents): text = contents
        Result.Err(_): panic("cannot read " + path)

    let max = 9223372036854775807
    let min = -9223372036854775807 - 1

    var totals = Map<String, int>()
    var overflowed = Set<String>()
    var in_queries = false

    for raw in text.split("\n")
        let line = strip_cr(raw)
        if in_queries
            let query = fields(line)
            if query.length() > 0
                let key = query.element_at(0)
                if overflowed.contains(key)
                    println(f"{key}=overflow")
