                            match totals.get(key)
                                Some(t): total = t
                                None: total = 0
                            let fits = (value > 0 and total <= max - value) or (value <= 0 and total >= min - value)
                            if fits
                                totals.set(key, total + value)
                            else
                                overflowed.add(key)
                    None: panic("bad value for key " + key)

